const loginData = $input.all()[0].json;
const d = loginData.data || {};

// Login failed: throw an explicit error (it ends up in the ntfy alert of the error workflow)
if (loginData.status !== 0 || !d.user || !d.authTicket) {
  const reason = d.step
    ? `action required "${d.step.type}" — open the LibreLinkUp app and accept (e.g. new terms of use)`
    : d.redirect
      ? `redirect to region "${d.region}" — use https://api-${d.region}.libreview.io in the LLU nodes`
      : 'unexpected response';
  throw new Error(`LibreLinkUp login failed (status ${loginData.status}): ${reason}`);
}

const userId = d.user.id;
const token = d.authTicket.token;

// account-id header = SHA256(user.id). The n8n task runner sandbox blocks the
// crypto module, so the hash is precomputed once and pasted here:
//   echo -n "<your LibreLinkUp user.id>" | sha256sum
const accountId = '<SHA256_OF_YOUR_LIBRELINKUP_USER_ID>';

if (accountId.startsWith('<')) {
  throw new Error(`account-id not configured. Your user.id is ${userId} — run: echo -n "${userId}" | sha256sum and paste the result in this node`);
}

return [{ json: { token, accountId, userId } }];

const data = $input.all()[0].json;
const connections = data.data;

if (!connections || connections.length === 0) {
  throw new Error('No LibreLinkUp connection found (is this a follower account with an accepted invitation?)');
}

const gm = connections[0].glucoseMeasurement;

if (!gm) {
  throw new Error('No glucose measurement available');
}

const trendMap = {
  1: 'DoubleUp',
  2: 'SingleUp',
  3: 'FortyFiveUp',
  4: 'Flat',
  5: 'FortyFiveDown',
  6: 'SingleDown',
  7: 'DoubleDown'
};

const now = Date.now();

const entry = {
  type: 'sgv',
  sgv: Math.round(gm.ValueInMgPerDl),
  date: now,
  dateString: new Date(now).toISOString(),
  direction: trendMap[gm.TrendArrow] || 'Flat',
  device: 'LibreLinkUp'
};

return [{ json: { entry, sgv: gm.ValueInMgPerDl, mmol: gm.Value, trend: gm.TrendArrow, isHigh: gm.isHigh, isLow: gm.isLow } }];

// ── Alert thresholds ─────────────────────────────────────────────
// Values in mmol/L (mg/dL = mmol/L × 18). Set a threshold to null to disable it.
const LOW_MMOL = 3.9;          // below → urgent "LOW" alert      (≈ 70 mg/dL)
const HIGH_MMOL = 10.0;        // above → urgent "HIGH" alert     (≈ 180 mg/dL)
const USE_LIBRE_FLAGS = true;  // also alert when LibreLinkUp itself flags isHigh/isLow
const NORMAL_EVERY_MIN = 15;   // silent "normal" notification every N minutes (multiple of 5)
// ─────────────────────────────────────────────────────────────────

const sgv = $json.sgv;
const mmol = $json.mmol;
const trend = $json.trend;

const trendArrow = { 1:'⬆⬆', 2:'⬆', 3:'↗', 4:'→', 5:'↘', 6:'⬇', 7:'⬇⬇' }[trend] || '→';

const isLow = (LOW_MMOL !== null && mmol < LOW_MMOL) || (USE_LIBRE_FLAGS && $json.isLow === true);
const isHigh = !isLow && ((HIGH_MMOL !== null && mmol > HIGH_MMOL) || (USE_LIBRE_FLAGS && $json.isHigh === true));
const isCritical = isLow || isHigh;

// The workflow runs every 5 min: send a normal reading only once per window
const shouldNotifyNormal = new Date().getMinutes() % NORMAL_EVERY_MIN < 5;

if (!isCritical && !shouldNotifyNormal) {
  return [{ json: { shouldSend: false } }];
}

const priority = isCritical ? 'urgent' : 'default';
const title = isLow ? '🔴 LOW GLUCOSE' : (isHigh ? '🟡 HIGH GLUCOSE' : '🩸 Glucose');
const tags = isCritical ? 'rotating_light,drop_of_blood' : 'drop_of_blood';
const body = mmol + ' mmol/L (' + Math.round(sgv) + ' mg/dL) ' + trendArrow;

return [{ json: { shouldSend: true, priority, title, tags, body } }];
